from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}
VALID_METHODS = ("card", "transfer")


def _tier_fee(tier: str) -> int | None:
    """Resolve an unknownable tier to its renewal fee, or None if unsupported."""
    return TIER_FEES.get(tier)


def _payment_error(payment: dict, fee: int) -> str | None:
    """Validate that a payment covers the given fee; return an error or None."""
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in VALID_METHODS:
        return "unsupported method"
    if payment["amount"] < fee:
        return "insufficient payment"
    return None


def _make_receipt(payment: dict, member_id: str, status: str, fee: int) -> str:
    return f"{payment['method']}:{member_id}:{status}:{fee}"


def _active(member: dict, fee: int):
    return "renewed", fee, None


def _lapsed(member: dict, fee: int):
    if (
        "expired_days" not in member
        or not isinstance(member["expired_days"], int)
        or member["expired_days"] < 0
    ):
        return None, None, "bad expiry"
    if member["expired_days"] <= GRACE_DAYS:
        return "renewed", fee + LATE_FEE, None
    return "reinstated", fee + REINSTATE_SURCHARGE, None


def _suspended(member: dict, fee: int):
    if (
        "strikes" not in member
        or not isinstance(member["strikes"], int)
        or member["strikes"] < 0
    ):
        return None, None, "bad strikes"
    if member["strikes"] >= MAX_STRIKES:
        return None, None, "too many strikes"
    return "reactivated", fee + fee // 2, None


PLANS = {
    "active": _active,
    "lapsed": _lapsed,
    "suspended": _suspended,
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return {"ok": False, "error": "bad member id"}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}

    plan = PLANS.get(status)
    if plan is None:
        return {"ok": False, "error": "unknown status"}

    fee = _tier_fee(member["tier"])
    if fee is None:
        return {"ok": False, "error": "unknown tier"}

    out_status, fee, guard_error = plan(member, fee)
    if guard_error is not None:
        return {"ok": False, "error": guard_error}

    error = _payment_error(payment, fee)
    if error is not None:
        return {"ok": False, "error": error}

    receipt = _make_receipt(payment, member["id"], out_status, fee)
    return {"ok": True, "status": out_status, "fee": fee, "receipt": receipt}

